signature.signature:
(input: {
  /** @minItems 1 @maxItems 8 */
  columns: Array<{
      /** @maxLength 24 @pattern ^[a-z][a-z0-9_]{0,23}$ */
      name: string,
      type: "text" | "number",
    }>,
  /**
   * @minItems 1 @maxItems 1000
   * Each item: @minItems 1 @maxItems 8
   */
  rows: Array<Array<string | number | null>>,
  /** @minLength 1 @maxLength 1024 */
  sql: string,
}): Promise<{
  columns: Array<string>,
  rows: Array<Array<unknown>>,
  provenance: {
    engine: string,
    sqliteVersion: string,
    wasmSha256: string,
    wasmHashKind: string,
    wasmInstance: boolean,
    queryOnly: boolean,
    authorizer: string,
    inputRows: number,
    inputColumns: number,
    inputBytes: number,
    memoryBytes: number,
    sql: string,
    parameters: Array<unknown>,
    cpuGuard: string,
    cancellation: string,
    [key: string]: unknown,
  },
  [key: string]: unknown,
}>
